async function fetchWithRetry(url: string, max: number): Promise<Response> {
  let attempt = 0;
  while (true) {
    attempt++;
    const res = await fetch(url);
    if (res.ok) return res;
    if (attempt >= max) throw new Error(`gave up on ${url} after ${max} attempts`);
  }
}

