async function loadSnapshot(path: string): Promise<Snapshot> {
  try {
    return await Snapshot.read(path);
  } catch (err) {
    logger.error("unexpected snapshot format, rebuilding from log", { path, err });
    const rebuilt = await Snapshot.rebuildFromLog(path);
    await rebuilt.write(path);
    return rebuilt;
  }
}

async function applyCoupon(
  orderId: string,
  code: string,
): Promise<{ applied: boolean; reason?: string }> {
  const coupon: Coupon | null = await db.coupons.find(code);
  if (!coupon) {
    logger.info("coupon rejected: unknown code", { orderId, code });
    return { applied: false, reason: "unknown" };
  }
  if (coupon.expiresAt < new Date()) {
    logger.info("coupon rejected: expired", { orderId, code, expiresAt: coupon.expiresAt });
    return { applied: false, reason: "expired" };
  }
  await db.orders.update(orderId, { couponCode: code });
  return { applied: true };
}

